/**
 * Fireworks burst system with strict pooling.
 *
 * All particle state lives in preallocated typed arrays. Free slots are
 * tracked by an explicit index stack, so allocation is O(1) and the pool
 * invariant (alive + free === poolSize) holds at all times.
 */

/** Deterministic PRNG (mulberry32). Returns floats in [0, 1). */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Create a pooled fireworks system.
 *
 * @param {object} [opts]
 * @param {number} [opts.poolSize=800]          Total particle capacity.
 * @param {number} [opts.particlesPerBurst=120] Slots claimed per burst.
 * @param {number} [opts.gravity=-9.8]          Gravitational acceleration on Y.
 * @param {number} [opts.lifeSec=2.2]           Particle lifetime in seconds.
 * @param {number} [opts.seed=1]                Seed for the burst RNG.
 */
export function createFireworks({
  poolSize = 800,
  particlesPerBurst = 120,
  gravity = -9.8,
  lifeSec = 2.2,
  seed = 1,
} = {}) {
  const n = poolSize;

  return {
    poolSize: n,
    particlesPerBurst,
    gravity,
    lifeSec,

    // Particle state (preallocated; index i valid iff alive[i] === 1)
    px: new Float32Array(n),
    py: new Float32Array(n),
    pz: new Float32Array(n),
    vx: new Float32Array(n),
    vy: new Float32Array(n),
    vz: new Float32Array(n),
    age: new Float32Array(n),
    alive: new Uint8Array(n),

    // Free-index stack: stack[0 .. stackTop-1] are the free slot ids
    stack: new Int32Array(n),
    stackTop: n,

    rng: mulberry32(seed),
  };
}

// Fill the free stack lazily on creation instead of per-call loops above.
// (Kept as an explicit init so createFireworks stays single-pass readable.)
export function _initFreeStack(fw) {
  for (let i = 0; i < fw.poolSize; i++) fw.stack[i] = i;
}

/**
 * Claim particlesPerBurst slots and spawn one radial burst at `origin`.
 * Throws if the pool would overflow.
 *
 * @returns {number[]} indices claimed by this burst
 */
export function burst(fw, origin) {
  const need = fw.particlesPerBurst;
  if (fw.stackTop < need) {
    throw new Error(
      `Pool overflow: need ${need} slots, only ${fw.stackTop} free ` +
        `(poolSize ${fw.poolSize})`
    );
  }

  const claimed = new Array(need);
  const [ox, oy, oz] = origin;

  for (let k = 0; k < need; k++) {
    const i = fw.stack[--fw.stackTop];
    claimed[k] = i;

    // Uniform direction via z-uniform + azimuth sampling
    const z = 2 * fw.rng() - 1; // cos(polar) in [-1, 1]
    const theta = 2 * Math.PI * fw.rng();
    const r = Math.sqrt(Math.max(0, 1 - z * z));
    const speed = 4 + 3 * fw.rng(); // in [4, 7]

    fw.px[i] = ox;
    fw.py[i] = oy;
    fw.pz[i] = oz;
    fw.vx[i] = r * Math.cos(theta) * speed;
    fw.vy[i] = z * speed;
    fw.vz[i] = r * Math.sin(theta) * speed;
    fw.age[i] = 0;
    fw.alive[i] = 1;
  }

  return claimed;
}

/**
 * Integrate all live particles by dt seconds. Expired particles (age >=
 * lifeSec) are returned to the free stack.
 *
 * @returns {number} number of particles recycled this step
 */
export function stepFireworks(fw, dt) {
  let recycled = 0;
  const { px, py, pz, vx, vy, vz, age, alive } = fw;
  const g = fw.gravity * dt;
  const limit = fw.lifeSec;

  for (let i = 0; i < fw.poolSize; i++) {
    if (alive[i] !== 1) continue;
    vx[i] += g;
    px[i] += vx[i] * dt;
    py[i] += vy[i] * dt;
    pz[i] += vz[i] * dt;
    age[i] += dt;
    if (age[i] >= limit) {
      alive[i] = 0;
      fw.stack[fw.stackTop++] = i;
      recycled++;
    }
  }
  return recycled;
}

/** Number of currently live particles. */
export function aliveCount(fw) {
  let c = 0;
  for (let i = 0; i < fw.poolSize; i++) if (aliveCheck(fw, i)) c++;
  return c;
}

function aliveCheck(fw, i) {
  return fw.alive[i] === 1 ? 1 : 0;
}

/** Number of slots sitting on the free stack. */
export function freeCount(fw) {
  return fw.stackTop;
}

