import { describe, it, expect } from 'vitest';
import {
  createFireworks,
  burst,
  stepFireworks,
  aliveCount,
  freeCount,
} from '../src/fireworks.js';

const EPS = 1e-6;

describe('fireworks pooling', () => {
  it('after one burst aliveCount is 120 and freeCount is poolSize - 120', () => {
    const fw = createFireworks({ poolSize: 800 });
    burst(fw, [0, 0, 0]);
    expect(aliveCount(fw)).toBe(120);
    expect(freeCount(fw)).toBe(800 - 120);
  });

  it('alive + free always equals poolSize across a 6s sim with bursts every 0.8s', () => {
    const poolSize = 800;
    const fw = createFireworks({ poolSize });
    const dt = 1 / 60;
    let nextBurst = 0;

    for (let t = 0; t <= 6 + 1e-9; t += dt) {
      if (t >= nextBurst - 1e-9 && nextBurst <= 6) {
        expect(() => burst(fw, [Math.random(), Math.random(), Math.random()]))
          .not.toThrow();
        nextBurst += 0.8;
      }
      stepFireworks(fw, dt);
      expect(aliveCount(fw) + freeCount(fw)).toBe(poolSize);
    }
    expect(nextBurst).toBeGreaterThan(6); // sanity: several bursts happened
  });

  it('all particles from one burst start at the origin', () => {
    const fw = createFireworks();
    const origin = [3.5, -2.25, 7];
    burst(fw, origin);
    for (let i = 0; i < fw.poolSize; i++) {
      if (fw.alive[i] !== 1) continue;
      expect(fw.px[i]).toBe(origin[0]);
      expect(fw.py[i]).toBe(origin[1]);
      expect(fw.pz[i]).toBe(origin[2]);
    }
  });

  it('after lifeSec + epsilon a lone burst is fully recycled', () => {
    const fw = createFireworks({ lifeSec: 2.2 });
    burst(fw, [0, 10, 0]);
    stepFireworks(fw, 2.2 + EPS);
    expect(aliveCount(fw)).toBe(0);
    expect(freeCount(fw)).toBe(800);
  });

  it('initial speeds are all in [4, 7] within 1e-9', () => {
    const fw = createFireworks();
    for (let b = 0; b < 5; b++) {
      burst(fw, [0, 0, 0]);
    }
    let seen = 0;
    for (let i = 0; i < fw.poolSize; i++) {
      if (fw.alive[i] !== 1) continue;
      const speed = Math.hypot(fw.vx[i], fw.vy[i], fw.vz[i]);
      expect(speed).toBeGreaterThanOrEqual(4 - 1e-9);
      expect(speed).toBeLessThanOrEqual(7 + 1e-9);
      seen++;
    }
    expect(seen).toBe(5 * 120);
  });

  it('same seed reproduces the same directions', () => {
    const mk = () =>
      createFireworks({ seed: 1234, poolSize: 400, particlesPerBurst: 100 });
    const a = mk();
    const b = mk();

    // Burn some RNG state identically on both to make the test stronger
    for (const fw of [a, b]) {
      burst(fw, [0, 5, 0]);
      stepFireworks(fw, 0.3);
      burst(fw, [1, 5, 1]);
    }

    for (let i = 0; i < a.poolSize; i++) {
      expect(Math.hypot(a.vx[i], a.vy[i], a.vz[i])).toBeCloseTo(
        Math.hypot(b.vx[i], b.vy[i], b.vz[i]),
        12
      );
      // Direction match: normalized velocity vectors equal
      const sa = Math.hypot(a.vx[i], a.vy[i], a.vz[i]) || 1;
      const sb = Math.hypot(b.vx[i], b.vy[i], b.vz[i]) || 1;
      expect(a.vx[i] / sa).toBeCloseTo(b.vx[i] / sb, 12);
      expect(a.vy[i] / sa).toBeCloseTo(b.vy[i] / sb, 12);
      expect(a.vz[i] / sa).toBeCloseTo(b.vz[i] / sb, 12);
    }
  });

  it('throws when a burst would overflow the pool', () => {
    const fw = createFireworks({ poolSize: 200, particlesPerBurst: 120 });
    burst(fw, [0, 0, 0]);
    expect(() => burst(fw, [0, 0, 0])).toThrow(/overflow/i);
  });
});

